const addTaskPositionAtEnd = db.prepare('INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position) SELECT ?, ?, COALESCE(MAX(position), 0) + 1 FROM task_project_positions WHERE project_id = ?');

